<script setup lang="ts">
import { ref } from 'vue'
import { useRouter } from 'vue-router'
import { Check, Sparkles, Save, Image as ImageIcon, Search, Scissors, Plus, ChevronDown } from 'lucide-vue-next'
import { api,patch,post,kindName } from '../api'
import MathText from './MathText.vue'
import CropEditor from './CropEditor.vue'
import Modal from './Modal.vue'
const props=defineProps<{question:any}>(),emit=defineEmits(['changed'])
const router=useRouter()
const q=ref(JSON.parse(JSON.stringify(props.question)))
const tags=ref(q.value.tags.join('、')),options=ref(q.value.options.join('\n'))
const error=ref(''),busy=ref(false),crop=ref(false),editing=ref(false),accepted=ref(false),showAnswer=ref(false),duplicates=ref<any[]|null>(null),splitOpen=ref(false)
const answer=ref({answer:'',explanation:'',rubric:''}),selected=ref(q.value.answers.find((a:any)=>a.status==='approved')?.id||q.value.answers[0]?.id||'')
const parts=ref([{number:q.value.number,stem:q.value.stem},{number:'',stem:''}])
async function run(fn:()=>Promise<any>){busy.value=true;error.value='';try{const result=await fn();if(result?.stem){q.value=result;selected.value=result.answers.find((a:any)=>a.status==='approved')?.id||result.answers[0]?.id||''}emit('changed');return result}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function save(){await run(()=>patch(`questions/${q.value.id}/`,{number:q.value.number,stem:q.value.stem,kind:q.value.kind,options:options.value.split('\n').filter(Boolean),tags:tags.value.split(/[、,，]/).map((s:string)=>s.trim()).filter(Boolean),grade:q.value.grade,chapter:q.value.chapter,difficulty:Number(q.value.difficulty),suggested_max_score:q.value.suggested_max_score,regions:q.value.regions,figure_regions:q.value.figure_regions||[],extracted_student_answer:q.value.extracted_student_answer}));editing.value=false}
async function addAnswer(){const result=await run(async()=>{await post(`questions/${q.value.id}/answer/`,answer.value);return api(`questions/${q.value.id}/`)});if(result){showAnswer.value=false;answer.value={answer:'',explanation:'',rubric:''}}}
async function split(){const result=await run(()=>post(`questions/${q.value.id}/split/`,{parts:parts.value.map(p=>({...p,regions:q.value.regions,kind:q.value.kind}))}));if(result)splitOpen.value=false}
async function clone(){await run(async()=>{await post(`questions/${q.value.id}/clone/`);await router.push('/questions?status=draft')})}
</script>
<template><article class="question-card"><header class="question-top"><div class="inline"><span class="question-number">{{q.number||'题'}}</span><span class="tag">{{kindName[q.kind]}}</span><span class="tag" :class="q.status==='approved'?'green':'amber'">{{q.status==='approved'?'已入库':'待审核'}}</span></div><span class="muted small">{{q.suggested_max_score}} 分 · 难度 {{q.difficulty}}/5</span></header><div v-if="error" class="notice danger">{{error}}</div>
 <template v-if="editing"><div class="form-grid"><label>题号<input v-model="q.number"/></label><label>题型<select v-model="q.kind"><option v-for="(name,key) in kindName" :value="key">{{name}}</option></select></label></div><label>题干（公式用 $…$）<textarea v-model="q.stem" rows="5"/></label><label>选项（每行一项）<textarea v-model="options" rows="3"/></label><div class="form-grid"><label>知识点（顿号分隔）<input v-model="tags"/></label><label>分值<input v-model="q.suggested_max_score" type="number" min="0.01" max="1000" step="0.01"/></label><label>难度<select v-model="q.difficulty"><option v-for="n in 5" :value="n">{{n}}</option></select></label><label>年级<input v-model="q.grade"/></label></div><label v-if="q.batch">提取的学生作答<textarea v-model="q.extracted_student_answer" rows="3"/></label><button class="button primary small" :disabled="busy" @click="save"><Save :size="15"/>保存修正</button></template>
 <template v-else><div class="question-stem"><MathText :text="q.stem"/></div><div v-if="q.options.length" class="options-grid"><MathText v-for="(option,index) in q.options" :key="index" :text="option"/></div><div class="tags"><span v-for="tag in q.tags" class="tag subtle">{{tag}}</span></div></template>
 <div v-if="q.regions.length" class="source-images"><img v-for="(r,i) in q.regions" :key="i" :src="`/api/pages/${r.page}/image/?bbox=${r.bbox.join(',')}`" alt="本题原始裁切图" loading="lazy"/></div>
 <div v-if="crop"><CropEditor v-for="(region,index) in q.regions" :key="index" :region="region" @update="q.regions[index]=$event;editing=true"/><p class="helper">配图单独保存，打印时不会夹带学生手写答案。先将上方区域调整为所需印刷配图，再点击添加。</p><button class="button secondary small" @click="q.figure_regions=[...(q.figure_regions||[]),...JSON.parse(JSON.stringify(q.regions))];editing=true">将当前区域添加为试题配图</button><div v-for="(figure,index) in q.figure_regions" :key="index"><CropEditor :region="figure" @update="q.figure_regions[index]=$event;editing=true"/><button class="text-button" @click="q.figure_regions.splice(index,1);editing=true">移除此配图</button></div></div>
 <div v-if="q.issues.length" class="notice warning"><strong>需要核对</strong><p v-for="issue in q.issues">{{issue}}</p></div>
 <div v-if="q.student_answer_present||q.extracted_student_answer" class="student-answer"><span class="mini-label">识别到的学生作答 · 与参考答案分开保存</span><MathText :text="q.extracted_student_answer||'（未能识别文字，请核对原图）'"/></div>
 <section class="answer-review"><div class="section-label"><span>参考答案</span><div class="inline"><button v-if="q.status==='approved'" class="text-button" :disabled="busy" @click="clone">另存修订副本</button><span class="muted small">选择一个版本确认</span></div></div><label v-for="a in q.answers" :key="a.id" class="answer-choice" :class="{selected:selected===a.id}"><input v-model="selected" type="radio" :value="a.id" :name="q.id"/><div><div class="inline"><span class="tag" :class="a.status==='approved'?'green':'subtle'">{{({printed:'随卷答案',ai:'AI生成',teacher:'教师填写',bank:'题库关联'} as any)[a.origin]}}</span><span class="small muted">{{a.status==='approved'?'已确认':'待审核'}}</span></div><MathText :text="a.answer"/><details v-if="a.explanation||a.rubric"><summary>解析与评分细则</summary><MathText :text="a.explanation+'\n'+a.rubric"/></details></div></label><p v-if="!q.answers.length" class="muted small">尚无参考答案，可填写答案或使用 AI 解题。</p>
 <div v-if="showAnswer" class="answer-form"><label>参考答案<textarea v-model="answer.answer" rows="2"/></label><label>解析<textarea v-model="answer.explanation" rows="3"/></label><label>评分细则<textarea v-model="answer.rubric" rows="2"/></label><button class="button secondary small" :disabled="busy||!answer.answer.trim()" @click="addAnswer">保存答案版本</button></div>
 <label v-if="q.issues.length" class="check-row"><input v-model="accepted" type="checkbox"/>我已核对并处理以上问题，确认题干与分值完整</label>
 </section><div v-if="duplicates" class="duplicate-results"><p class="helper">文字相似结果，需核对公式和配图后关联。</p><div v-for="d in duplicates" class="duplicate-row"><MathText :text="d.question.stem"/><button class="button secondary small" :disabled="busy" @click="run(()=>post(`questions/${q.id}/link/`,{question_id:d.question.id}))">关联答案</button></div><p v-if="!duplicates.length" class="muted">未找到相似题，可独立录入。</p></div>
 <footer class="question-actions"><div class="inline wrap"><button class="text-button" :disabled="busy" @click="editing=!editing"><Save :size="14"/>修正题目</button><button v-if="q.regions.length" class="text-button" @click="crop=!crop"><ImageIcon :size="14"/>调整切题</button><button class="text-button" :disabled="busy" @click="showAnswer=!showAnswer"><Plus :size="14"/>填写答案</button><button class="text-button" :disabled="busy" @click="run(()=>post(`questions/${q.id}/solve/`))"><Sparkles :size="14"/>AI 解题</button><button class="text-button" :disabled="busy" @click="run(async()=>{duplicates=await api(`questions/${q.id}/duplicates/`)})"><Search :size="14"/>查重</button><button v-if="q.status==='draft'" class="text-button" @click="splitOpen=true"><Scissors :size="14"/>拆题</button></div><button class="button primary small" :disabled="busy||!selected||editing||(q.issues.length&&!accepted)" @click="run(()=>post(`questions/${q.id}/approve/`,{answer_id:selected,confirm_issues:accepted}))"><Check :size="16"/>{{busy?'处理中…':q.status==='approved'?'重新确认':'确认入库'}}</button></footer>
 <Modal v-if="splitOpen" title="拆分为两道题" @close="splitOpen=false"><p class="helper">拆分后需重新审核答案；可分别调整两题的原图范围。</p><div v-for="(part,index) in parts"><h3>题目 {{index+1}}</h3><label>题号<input v-model="part.number"/></label><label>题干<textarea v-model="part.stem" rows="4"/></label></div><button class="button primary" :disabled="busy||parts.some(p=>!p.stem.trim())" @click="split">确认拆分</button></Modal>
 </article></template>
